declare_lint_rule! {
    /// Detects JSX text nodes ending with `$` immediately before a JSX expression child.
    ///
    /// When migrating from template literal string interpolation to JSX, it is easy
    /// to leave behind a stray `$` before a curly-brace expression. Unlike in a
    /// template literal, the `$` is not part of the interpolation syntax in JSX and
    /// will be rendered as literal text.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```jsx,expect_diagnostic
    /// <div>Total: {total}${value}</div>;
    /// ```
    ///
    /// ```jsx,expect_diagnostic
    /// <div>price${price}</div>;
    /// ```
    ///
    /// ### Valid
    ///
    /// ```jsx
    /// <div>${value}</div>;
    /// ```
    ///
    /// ```jsx
    /// <div>{value}</div>;
    /// ```
    ///
    /// ```js
    /// const text = `${value}`;
    /// ```
    ///
    pub NoJsxLeakedDollar {
        version: "next",
        name: "noJsxLeakedDollar",
        language: "jsx",
        recommended: false,
        fix_kind: FixKind::Unsafe,
    }
}

impl Rule for NoJsxLeakedDollar {
    type Query = Ast<JsxText>;
    type State = ();
    type Signals = Option<Self::State>;
    type Options = NoJsxLeakedDollarOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let node = ctx.query();
        let value_token = node.value_token().ok()?;
        let text = value_token.text();

        // The offending text node must end with a `$` character.
        if !text.ends_with('$') {
            return None;
        }

